prompt --application/shared_components/navigation/lists/custom_menu
begin
wwv_flow_imp_shared.create_list(
 p_id=>wwv_flow_imp.id(9838360875980221)
,p_name=>'Custom Menu'
,p_list_type=>'SQL_QUERY'
,p_list_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    LEVEL,',
'    M.MENU_NAME AS LABEL,',
'',
'    CASE',
'        WHEN M.PAGE_ID IS NOT NULL THEN',
'            ''f?p=''||:APP_ID||'':''||M.PAGE_ID||'':''||:APP_SESSION',
'    END AS TARGET,',
'',
'    NULL AS IS_CURRENT,',
'    M.ICON AS IMAGE,',
'    NULL AS IMAGE_ATTRIBUTE,',
'    NULL AS IMAGE_ALT_ATTRIBUTE,',
'    M.DISPLAY_SEQ AS SEQUENCE,',
'    NULL ATTRIBUTE_01,',
'    NULL ATTRIBUTE_02,',
'    NULL ATTRIBUTE_03,',
'    NULL ATTRIBUTE_04,',
'    NULL ATTRIBUTE_05,',
'    M.ID AS VALUE,',
'    M.PARENT_ID AS PARENT_VALUE',
'',
'FROM XH_MENU_MASTER M',
'',
'WHERE M.STATUS=''Y''',
'',
'AND EXISTS',
'(',
'    SELECT 1',
'    FROM XH_USER_ROLE UR',
'         JOIN XH_ROLE_MENU RM',
'           ON RM.XH_ROLE_ID = UR.XH_ROLE_ID',
'    WHERE UR.XH_USER_ID = :G_USER_ID',
'      AND RM.XH_MENU_ID = M.ID',
'      AND RM.CAN_VIEW = ''Y''',
')',
'',
'START WITH M.PARENT_ID IS NULL',
'CONNECT BY PRIOR M.ID = M.PARENT_ID',
'',
'ORDER SIBLINGS BY M.DISPLAY_SEQ;'))
,p_list_status=>'PUBLIC'
);
end;
