prompt --application/shared_components/security/authorizations/is_engineer
begin
wwv_flow_imp_shared.create_security_scheme(
 p_id=>wwv_flow_imp.id(8945246661343615)
,p_name=>'IS_ENGINEER'
,p_scheme_type=>'NATIVE_FUNCTION_BODY'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_role VARCHAR2(20);',
'BEGIN',
'    SELECT ROLE INTO v_role ',
'      FROM XH_USERS ',
'     WHERE UPPER(USER_NAME) = UPPER(:APP_USER) ',
'       AND STATUS = ''Y'';',
'       ',
'    RETURN v_role IN (''ENGINEER'', ''DISPATCHER'', ''MANAGER'');',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        RETURN FALSE;',
'END;'))
,p_caching=>'BY_USER_BY_SESSION'
);
end;
/
