wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(9159323682636560)
,p_plug_name=>'Work Orders'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(8826521314196829)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    WO.ID,',
'    WO.PARTNER_REF_ID,',
'    C.NAME AS CUSTOMER_NAME,',
'    SP.PRIORITY_CODE,',
'    WO.STATUS,',
'    U.FULL_NAME AS ENGINEER_NAME,',
'    TO_CHAR(WO.SCHEDULED_START, ''DD-MON-YYYY HH24:MI'') AS SCHEDULED_START,',
'    TO_CHAR(WO.SCHEDULED_END, ''DD-MON-YYYY HH24:MI'') AS SCHEDULED_END,',
'    TO_CHAR(WO.SLA_RESPONSE_DEADLINE, ''DD-MON-YYYY HH24:MI'') AS SLA_RESPONSE_DEADLINE,',
'    TO_CHAR(WO.SLA_RESOLVE_DEADLINE, ''DD-MON-YYYY HH24:MI'') AS SLA_RESOLVE_DEADLINE,',
'    WO.TOTAL_PARTS_COST,',
'    TO_CHAR(WO.CREATED_DATE, ''DD-MON-YYYY HH24:MI'') AS CREATED_DATE',
'FROM XH_WORK_ORDERS WO,',
'     XH_CUSTOMERS C,',
'     XH_SLA_PRIORITIES SP,',
'     XH_USERS U',
'WHERE WO.XH_CUSTOMER_ID = C.ID',
'  AND WO.XH_PRIORITY_ID = SP.ID(+)',
'  AND WO.XH_ASSIGNED_ENGINEER_ID = U.ID(+)',
'  --AND UPPER(U.USER_NAME) = UPPER(:APP_USER)',
'  AND  (',
'        EXISTS (',
'            SELECT 1',
'            FROM XH_USERS LOGIN_USER',
'            WHERE UPPER(LOGIN_USER.USER_NAME) = UPPER(:APP_USER)',
'              AND LOGIN_USER.STATUS = ''Y''',
'              AND LOGIN_USER.ROLE IN (''DISPATCHER'', ''MANAGER'')',
'        )',
'        OR',
'        (',
'            UPPER(:APP_USER) = UPPER(U.USER_NAME)',
'        )',
'    )',
'',
'ORDER BY WO.CREATED_DATE asc;'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
,p_prn_page_header=>'Work Orders'
);
