'SELECT',
'    P.ID,',
'    --P.XH_WORK_ORDER_ID,',
'    (SELECT PARTNER_REF_ID FROM XH_WORK_ORDERS WHERE ID=P.XH_WORK_ORDER_ID)WORK_WORDER_REF,',
'   -- P.XH_PART_ID,',
'    (SELECT PART_NUMBER FROM XH_PARTS WHERE ID=P.XH_PART_ID)PART_NUMBER,',
'    (SELECT NAME FROM XH_PARTS WHERE ID=P.XH_PART_ID)NAME,',
'    P.QUANTITY_USED,',
'    P.UNIT_COST,',
'    P.QUANTITY_USED * p.UNIT_COST AS TOTAL_COST,',
'    P.CONSUMED_DATE',
'FROM XH_WORK_ORDER_PARTS P ',
' ',
'where     P.XH_WORK_ORDER_ID = :P5_WORK_ORDER_ID '))
