 p_id=>wwv_flow_imp.id(9515913667616208)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'COMPLETE WORK ORDER'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_message VARCHAR2(4000);',
'BEGIN',
'',
'    PKG_XH_ENGINEER.COMPLETE_WORK_ORDER( TO_NUMBER(:P5_WORK_ORDER_ID), :APP_USER, v_message',
'    );',
'',
'    IF v_message IS NOT NULL THEN',
'        APEX_ERROR.ADD_ERROR(',
'            p_message          => v_message,',
'            p_display_location => APEX_ERROR.C_INLINE_IN_NOTIFICATION',
'        );',
'    END IF;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(9515551876616204)
,p_process_success_message=>'Order complete'
);
