,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'APPROVED WORK ORDER'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
' XH_APPROVE_WORK_ORDER(TO_NUMBER(:P5_WORK_ORDER_ID),:APP_USER);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(9515608861616205)
,p_process_success_message=>'Work order approved successful..'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9216425064789616)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load Work Order Details'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT',
'        C.NAME,',
'        WO.STATUS,',
'        WO.APPROVAL_STATUS,',
'        SP.PRIORITY_CODE,',
'        WO.PARTNER_REF_ID,',
'        U.FULL_NAME,',
'        WO.SCHEDULED_START,',
'        WO.SCHEDULED_END',
'    INTO',
'        :P5_CUSTOMER_NAME,',
'        :P5_STATUS,',
'        :P5_APPROVAL_STATUS,',
'        :P5_PRIORITY,',
'        :P5_PARTNER_REF_ID,',
'        :P5_ENGINEER_NAME,',
'        :P5_SCHEDULED_START,',
'        :P5_SCHEDULED_END',
'    FROM XH_WORK_ORDERS WO,',
'         XH_CUSTOMERS C,',
'         XH_SLA_PRIORITIES SP,',
'         XH_USERS U',
'    WHERE WO.XH_CUSTOMER_ID = C.ID(+)',
'      AND WO.XH_PRIORITY_ID = SP.ID(+)',
'      AND WO.XH_ASSIGNED_ENGINEER_ID = U.ID(+)',
'      AND WO.ID = :P5_WORK_ORDER_ID;',
'',
'    -- Calculate Total Parts Cost',
'    SELECT',
'        NVL(SUM(QUANTITY_USED * UNIT_COST), 0)',
'    INTO',
'        :P5_TOTAL_PARTS_COST',
'    FROM XH_WORK_ORDER_PARTS',
'    WHERE XH_WORK_ORDER_ID = :P5_WORK_ORDER_ID;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Work Order not found.''',
'        );',
'END;'))
,p_process_clob_language=>'PLSQL'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9516140076616210)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>' Start Work Order'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'   PKG_XH_ENGINEER.START_WORK_ORDER( to_number(:P5_WORK_ORDER_ID), :APP_USER);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(9516048418616209)
