'BEGIN',
'    PKG_XH_ENGINEER.UPDATE_STATUS( to_number(:P5_WORK_ORDER_ID), ''ON HOLD'', :APP_USER );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(9516212223616211)
,p_process_success_message=>'Work order on hold successful..'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9516586005616214)
,p_process_sequence=>30
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'RESUME WORK ORDER'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'',
'    PKG_XH_ENGINEER.UPDATE_STATUS( to_number(:P5_WORK_ORDER_ID), ''IN PROGRESS'', :APP_USER );',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(9516363537616212)
,p_process_success_message=>'Work order In Progress successful...'
);
end;
